const jsonBody = insomnia.response.json();
const status = insomnia.response.code ?? insomnia.response.status;

insomnia.test('returns HTTP 200', () => {
  insomnia.expect(status).to.eql(200);
});

insomnia.test('returns seeded games', () => {
  insomnia.expect(jsonBody).to.be.an('array');
  insomnia.expect(jsonBody.length).to.be.greaterThan(0);
  insomnia.expect(jsonBody[0]).to.include({
    id: 1,
    title: 'The Legend of Zelda: Breath of the Wild',
    genre: 'Adventure',
    platform: 'Nintendo Switch',
    releaseYear: '2017',
  });
});

const jsonBody = insomnia.response.json();
const status = insomnia.response.code ?? insomnia.response.status;

insomnia.test('returns HTTP 200', () => {
  insomnia.expect(status).to.eql(200);
});

insomnia.test('returns game by ID', () => {
  insomnia.expect(jsonBody).to.include({
    id: 1,
    title: 'The Legend of Zelda: Breath of the Wild',
    genre: 'Adventure',
    platform: 'Nintendo Switch',
    releaseYear: '2017',
  });
});

const jsonBody = insomnia.response.json();
const status = insomnia.response.code ?? insomnia.response.status;

insomnia.test('returns HTTP 400', () => {
  insomnia.expect(status).to.eql(400);
});

insomnia.test('returns game not found error', () => {
  insomnia.expect(jsonBody.message).to.eql('Game id not found in database.');
  insomnia.expect(jsonBody.errors).to.include('Request body is not valid.');
});

const jsonBody = insomnia.response.json();
const status = insomnia.response.code ?? insomnia.response.status;

insomnia.test('returns HTTP 200', () => {
  insomnia.expect(status).to.eql(200);
});

insomnia.test('creates game', () => {
  insomnia.expect(jsonBody.id).to.be.a('number');
  insomnia.expect(jsonBody).to.include({
    title: 'Tetris',
    genre: 'Puzzle',
    platform: 'Nintendo Switch',
    releaseYear: '1989',
  });
});

insomnia.environment.set('created_game_id', jsonBody.id);

const jsonBody = insomnia.response.json();
const status = insomnia.response.code ?? insomnia.response.status;

insomnia.test('returns HTTP 400', () => {
  insomnia.expect(status).to.eql(400);
});

insomnia.test('returns required fields error', () => {
  insomnia.expect(jsonBody.message).to.eql('All fields (title, genre, platform, releaseYear) are required.');
  insomnia.expect(jsonBody.errors).to.include('Request body is not valid.');
});

const jsonBody = insomnia.response.json();
const status = insomnia.response.code ?? insomnia.response.status;

insomnia.test('returns HTTP 400', () => {
  insomnia.expect(status).to.eql(400);
});

insomnia.test('returns invalid year error', () => {
  insomnia.expect(jsonBody.message).to.eql('Release year must be a valid four-digit year.');
  insomnia.expect(jsonBody.errors).to.include('Request body is not valid.');
});

const jsonBody = insomnia.response.json();
const status = insomnia.response.code ?? insomnia.response.status;
const createdGameId = Number(insomnia.environment.get('created_game_id'));

insomnia.test('returns HTTP 200', () => {
  insomnia.expect(status).to.eql(200);
});

insomnia.test('applies partial update', () => {
  insomnia.expect(jsonBody).to.include({
    id: createdGameId,
    title: 'Tetris',
    genre: 'Puzzle',
    platform: 'PlayStation 5',
    releaseYear: '2026',
  });
});

const jsonBody = insomnia.response.json();
const status = insomnia.response.code ?? insomnia.response.status;

insomnia.test('returns HTTP 400', () => {
  insomnia.expect(status).to.eql(400);
});

insomnia.test('returns invalid year error', () => {
  insomnia.expect(jsonBody.message).to.eql('Release year must be a valid four-digit year.');
  insomnia.expect(jsonBody.errors).to.include('Request body is not valid.');
});

const jsonBody = insomnia.response.json();
const status = insomnia.response.code ?? insomnia.response.status;
const createdGameId = Number(insomnia.environment.get('created_game_id'));

insomnia.test('returns HTTP 200', () => {
  insomnia.expect(status).to.eql(200);
});

insomnia.test('deletes created game', () => {
  insomnia.expect(jsonBody.id).to.eql(createdGameId);
  insomnia.expect(jsonBody.title).to.eql('Tetris');
});

